/**
 * PIR Function Node (documented)
 *
 * Overview
 * - This Function node implements a PIR-driven lighting controller with:
 *   - PIR-triggered auto-ON (mode 'pir')
 *   - Manual external ON/OFF handling (mode 'manual')
 *   - Lux constraints:
 *       - lux_min at activation (prevents PIR ON if ambient is bright)
 *       - lux_max while ON in PIR mode (turn off when ambient becomes bright)
 *       - lux_max_manual while ON in MANUAL mode (turn off when ambient becomes bright when user turned light on manually)
 *         - Note: setting lux_max_manual to 0 or leaving it empty disables this manual-mode lux behavior.
 *       - desativa_lux_manual (bool): when true, dynamically disables the lux_max_manual feature so ambient lux
 *           crossing lux_max_manual will NOT schedule a pir_off while in manual mode (NEW). Can be overridden at runtime
 *           by sending msg.desativa_lux_manual (boolean) to the function — that override takes precedence for the current message.
 *   - Three "desativa" (disable) entities that, when any is true, block PIR activation;
 *     if any becomes true while the lamp is ON in modo 'pir', the lamp is scheduled to
 *     turn OFF using t_off_s (via pir_off timer).
 *   - Persistence of state (in context.pir_state) and of scheduled timers (timestamps) so timers
 *     survive Node-RED restarts; a lightweight setTimeout executes timers, and a
 *     fallback watcher runs every 30s to catch any expired persisted timers if a
 *     setTimeout was lost during a reload.
 *   - "Delayed activation on lux drop" — if a PIR/presence signal was received
 *     but the lamp was NOT turned on because ambient lux was >= lux_min, the node
 *     remembers that a presence is active (pending). If later the lux sensor falls
 *     below lux_min while the presence is still active (and the PIR pulse is recent),
 *     the node will behave as if a new PIR pulse occurred and will turn the light on (modo 'pir').
 *   - pending_reactivate — if the lamp was turned OFF by pir_off due to lux >= lux_max(_manual)
 *     while presence is still detected, the node will mark pending_reactivate and will re-evaluate
 *     turning it back ON when lux falls below lux_min (within a timeout).
 *
 * New init/status features and debug-suppression:
 * - Accepts an `init` message (msg.topic === 'init' or msg.initial === true) with payload object:
 *     { desativa1, desativa2, desativa3, desativa_lux_manual, lastLux, light_on }
 *   The function will apply and persist these values immediately.
 * - Send msg.topic='status' or msg._status === true to get current state snapshot (debug & output[1]).
 * - Debug messages are suppressed during restore/init replay to avoid flooding the debug pane on deploy.
 *   There is also a short dedupe window for repeated identical debug messages.
 *
 * Outputs:
 * - [0] => ON messages (payload:'on', entity_id: cfg.input_entidade)
 * - [1] => OFF or status messages (payload:'off' or 'status', _state: snapshot)
 * - [2] => DEBUG messages (when dbg=true and not suppressed)
 *
 * Environment variables (subflow instance variables)
 * - input_entidade, lux_entidade, lux_min, lux_max, lux_max_manual, desativa_lux_manual,
 *   t_max_on_m, t_off_s, desativa_entidade, desativa_entidade2, desativa_entidade3, dbg, ignore_after_manual_ms,
 *   pending_pir_max_ms, pending_reactivate_max_ms
 *
 */

(function () {

  // === Configuration and environment reading ===
  const cfg = {
    input_entidade: (env.get('input_entidade') || '').toString(),
    lux_entidade: (env.get('lux_entidade') || '').toString(),
    lux_min: Number(env.get('lux_min') || 0),
    lux_max: (function () { const v = env.get('lux_max'); const n = Number(v); return (v === undefined || v === null || v === '') ? NaN : (isNaN(n) ? NaN : n); })(),
    lux_max_manual: (function () { const v = env.get('lux_max_manual'); const n = Number(v); return (v === undefined || v === null || v === '') ? NaN : (isNaN(n) ? NaN : n); })(),
    desativa_lux_manual: (String(env.get('desativa_lux_manual') || 'false').toLowerCase() === 'true'),
    t_max_on_m: Number(env.get('t_max_on_m') || 300),
    t_off_s: Number(env.get('t_off_s') || 1),
    desativa_entidade: (env.get('desativa_entidade') || '').toString(),
    desativa_entidade2: (env.get('desativa_entidade2') || '').toString(),
    desativa_entidade3: (env.get('desativa_entidade3') || '').toString(),
    dbg: (String(env.get('dbg') || 'false').toLowerCase() === 'true'),
    ignore_after_manual_ms: Number(env.get('ignore_after_manual_ms') || 20000),
    pending_pir_max_ms: Number(env.get('pending_pir_max_ms') || 120000),
    pending_reactivate_max_ms: Number(env.get('pending_reactivate_max_ms') || 120000)
  };

  // Defensive defaults
  if (!isFinite(cfg.t_max_on_m) || cfg.t_max_on_m <= 0) cfg.t_max_on_m = 300;
  if (!isFinite(cfg.pending_pir_max_ms) || cfg.pending_pir_max_ms <= 0) cfg.pending_pir_max_ms = 120000;
  if (!isFinite(cfg.pending_reactivate_max_ms) || cfg.pending_reactivate_max_ms <= 0) cfg.pending_reactivate_max_ms = 120000;

  // Treat 0 or empty for lux_max_manual as disabled
  if (!isFinite(cfg.lux_max_manual) || cfg.lux_max_manual <= 0) cfg.lux_max_manual = NaN;

  // Derived flags based on env
  const hasLuxEntity = !!cfg.lux_entidade;
  const luxMinActive = hasLuxEntity && Number.isFinite(cfg.lux_min) && cfg.lux_min > 0;
  const luxMaxActive = hasLuxEntity && Number.isFinite(cfg.lux_max) && cfg.lux_max > 0;
  const luxMaxManualActive = hasLuxEntity && Number.isFinite(cfg.lux_max_manual) && cfg.lux_max_manual > 0;

  // === Helpers ===
  function safeStringify(v) { try { return JSON.stringify(v); } catch (e) { return String(e); } }
  let msgDbgEnabled = Boolean(cfg.dbg); // will be updated per message

  // --- Suppress debug during restore/replay to avoid flood on deploy
  let suppressReplayDebug = true;
  // --- Deduplicate debug messages with a short window
  const debugCache = new Map();
  const DEBUG_DEDUPE_WINDOW_MS = 1000;

  // debugSend: send to debug output only when msgDbgEnabled true AND not suppressed.
  function debugSend(obj) {
    try {
      if (!msgDbgEnabled) return;
      if (suppressReplayDebug) return;
      const key = (obj && typeof obj.payload !== 'undefined') ? String(obj.payload) : safeStringify(obj);
      const now = Date.now();
      const last = debugCache.get(key);
      if (last && (now - last) < DEBUG_DEDUPE_WINDOW_MS) return;
      debugCache.set(key, now);
      if (debugCache.size > 5000) {
        const cutoff = now - (DEBUG_DEDUPE_WINDOW_MS * 5);
        for (const [k, ts] of debugCache) if (ts < cutoff) debugCache.delete(k);
      }
      node.send([null, null, obj]);
    } catch (e) { try { node.warn('[PIR][debugSend] ' + e); } catch (e) { } }
  }
  function dbg(kind, ...parts) {
    try {
      if (!msgDbgEnabled) return;
      if (suppressReplayDebug) return;
      const text = '[PIR][' + kind + '] ' + parts.map(p => (typeof p === 'string') ? p : safeStringify(p)).join(' ');
      debugSend({ payload: text, _debug: true, _kind: kind, _ts: Date.now() });
    } catch (e) { try { node.warn('[PIR][dbg-error] ' + e); } catch (e) { } }
  }

  function parseBoolAny(v) {
    if (v === null || v === undefined) return undefined;
    if (typeof v === 'boolean') return v;
    if (typeof v === 'number') return v !== 0;
    if (typeof v === 'string') {
      const s = v.trim().toLowerCase();
      if (s === 'true' || s === 'on' || s === '1' || s === 'yes') return true;
      if (s === 'false' || s === 'off' || s === '0' || s === 'no') return false;
      return undefined;
    }
    if (typeof v === 'object') {
      if (typeof v.state !== 'undefined') return parseBoolAny(v.state);
      if (v.new_state && typeof v.new_state.state !== 'undefined') return parseBoolAny(v.new_state.state);
      if (v.data && v.data.new_state && typeof v.data.new_state.state !== 'undefined') return parseBoolAny(v.data.new_state.state);
      if (v.payload) return parseBoolAny(v.payload);
      if (v.value) return parseBoolAny(v.value);
    }
    return undefined;
  }

  function extractLuxFromPayload(payload) {
    if (payload === null || payload === undefined) return NaN;
    if (typeof payload === 'number') return payload;
    if (typeof payload === 'string') {
      const n = Number(payload); return isNaN(n) ? NaN : n;
    }
    if (typeof payload === 'object') {
      const candidates = [
        payload.state,
        payload.payload,
        payload.value,
        payload.current_state,
        (payload.new_state && payload.new_state.state),
        (payload.data && payload.data.new_state && payload.data.new_state.state),
        (payload.data && payload.data.state),
        (payload.attributes && payload.attributes.state)
      ];
      for (const c of candidates) {
        if (c === undefined || c === null) continue;
        if (typeof c === 'number') return c;
        if (typeof c === 'string' && !isNaN(Number(c))) return Number(c);
      }
    }
    return NaN;
  }

  function normEntity(e) {
    if (!e && e !== '') return '';
    try { return String(e).trim().toLowerCase(); } catch (e) { return ''; }
  }

  // === Context state and runtime timers ===
  const nodeCtx = context;
  let state = nodeCtx.get('pir_state') || {
    modo: 'livre',
    light_on: false,
    lastLux: null,
    lastPirAt: 0,
    pir_active: false,
    pending_pir: false,
    pending_reactivate: false,
    pending_reactivate_since: 0,
    desativa1: false,
    desativa2: false,
    desativa3: false,
    desativa_lux_manual: cfg.desativa_lux_manual,
    timers: {},
    ignore_until: 0,
    _last_self_off_ms: 0,
    _last_self_off_entity: ''
  };
  let runtimeTimers = nodeCtx.get('runtime_timers') || {};

  // Initialization guard to clear runtime timers once
  if (!nodeCtx.get('pir_runtime_initialized')) {
    Object.keys(runtimeTimers).forEach(k => { try { clearTimeout(runtimeTimers[k]); } catch (e) { } });
    runtimeTimers = {};
    nodeCtx.set('runtime_timers', runtimeTimers);
    nodeCtx.set('pir_runtime_initialized', true);
    if (cfg.dbg && !suppressReplayDebug) debugSend({ payload: '[PIR] runtime timers cleaned at init', _debug: true });
  }

  // === Watcher and Timer helpers ===
  function startWatcher() {
    if (runtimeTimers['_watcher']) return;
    runtimeTimers['_watcher'] = setInterval(() => {
      try {
        state = nodeCtx.get('pir_state') || state;
        const now = Date.now();
        const timers = state.timers || {};
        for (const name of Object.keys(timers)) {
          const entry = timers[name];
          if (!entry || !entry.until) continue;
          if (entry.until <= now) {
            delete state.timers[name];
            nodeCtx.set('pir_state', state);
            if (name === 'pir_off') onPirOffTimeout();
            else if (name === 'max_on') onMaxOnTimeout();
            else dbg('watcher', 'no handler for', name);
          }
        }
      } catch (e) { node.error(e); }
    }, 30000);
    nodeCtx.set('runtime_timers', runtimeTimers);
  }
  function clearRuntimeTimer(name) {
    const id = runtimeTimers[name];
    if (id) { try { clearTimeout(runtimeTimers[name]); } catch (e) { } }
    delete runtimeTimers[name];
    if (state.timers && state.timers[name]) {
      delete state.timers[name];
      dbg('timers', 'removed persisted timer', name);
    }
    nodeCtx.set('pir_state', state);
    nodeCtx.set('runtime_timers', runtimeTimers);
  }
  function scheduleTimer(name, ms, handler) {
    dbg('timers', 'scheduling', name, 'in_ms', ms);
    const until = Date.now() + ms;
    state.timers = state.timers || {};
    state.timers[name] = { until };
    nodeCtx.set('pir_state', state);

    if (runtimeTimers[name]) { try { clearTimeout(runtimeTimers[name]); } catch (e) { } delete runtimeTimers[name]; }

    const id = setTimeout(() => {
      dbg('timers', 'timer fired (setTimeout)', name);
      delete runtimeTimers[name];
      if (state.timers && state.timers[name]) delete state.timers[name];
      nodeCtx.set('runtime_timers', runtimeTimers);
      nodeCtx.set('pir_state', state);
      try { handler(); } catch (e) { node.error(e); }
    }, ms);

    runtimeTimers[name] = id;
    nodeCtx.set('runtime_timers', runtimeTimers);

    if (cfg.dbg && !suppressReplayDebug) debugSend({ payload: '[PIR] timers snapshot', _timers: JSON.parse(JSON.stringify(state.timers)), _debug: true });
    startWatcher();
  }
  function scheduleTimerAt(name, until, handler) {
    const rem = until - Date.now();
    dbg('timers', 'scheduleTimerAt', name, 'until', until, 'rem_ms', rem);
    if (rem <= 0) {
      setTimeout(() => {
        if (state.timers && state.timers[name]) delete state.timers[name];
        nodeCtx.set('pir_state', state);
        try { handler(); } catch (e) { node.error(e); }
      }, 0);
    } else scheduleTimer(name, rem, handler);
  }

  // --- Apply init payload helper ---
  function applyInitPayload(payloadObj) {
    if (!payloadObj || typeof payloadObj !== 'object') return false;
    let changed = false;
    if (typeof payloadObj.desativa1 !== 'undefined') { state.desativa1 = Boolean(payloadObj.desativa1); changed = true; }
    if (typeof payloadObj.desativa2 !== 'undefined') { state.desativa2 = Boolean(payloadObj.desativa2); changed = true; }
    if (typeof payloadObj.desativa3 !== 'undefined') { state.desativa3 = Boolean(payloadObj.desativa3); changed = true; }
    if (typeof payloadObj.desativa_lux_manual !== 'undefined') { state.desativa_lux_manual = Boolean(payloadObj.desativa_lux_manual); changed = true; }
    if (typeof payloadObj.lastLux !== 'undefined' && !isNaN(Number(payloadObj.lastLux))) { state.lastLux = Number(payloadObj.lastLux); changed = true; }
    if (typeof payloadObj.light_on !== 'undefined') { state.light_on = Boolean(payloadObj.light_on); changed = true; }
    if (changed) {
      nodeCtx.set('pir_state', state);
      debugSend({ payload: '[PIR] init applied', _state: JSON.parse(JSON.stringify(state)), _debug: true });
      dbg('init', 'applied init payload', state);
    }
    return changed;
  }

  // === Timer handlers and emitOff ===
  function emitOff(reason) {
    clearRuntimeTimer('pir_off');
    clearRuntimeTimer('max_on');

    state._last_self_off_ms = Date.now();
    state._last_self_off_entity = normEntity(cfg.input_entidade);

    state.light_on = false;
    state.modo = 'livre';
    state.ignore_until = 0;
    state.pending_pir = false;
    nodeCtx.set('pir_state', state);

    node.status({ fill: 'green', shape: 'ring', text: 'luz: off (' + reason + ')' });
    const outOff = { payload: 'off', _reason: reason, _state: JSON.parse(JSON.stringify(state)), entity_id: cfg.input_entidade };
    node.send([null, outOff, null]);
    debugSend({ payload: '[PIR] emitted OFF ' + reason, _debug: true });
    dbg('general', 'emitOff', reason, { self_off_entity: state._last_self_off_entity, self_off_ms: state._last_self_off_ms });
  }
  function onPirOffTimeout() {
    dbg('timers', 'onPirOffTimeout; modo=', state.modo, 'light_on=', state.light_on);
    if (state.light_on) {
      const presenceStill = Boolean(state.pir_active);
      if (presenceStill) {
        state.pending_reactivate = true;
        state.pending_reactivate_since = Date.now();
        nodeCtx.set('pir_state', state);
        dbg('timers', 'set pending_reactivate because pir_off fired while pir_active is true', { pending_reactivate_since: state.pending_reactivate_since });
      }
      clearRuntimeTimer('pir_off');
      emitOff('pir_off_timeout');
    } else {
      dbg('timers', 'pir_off_timeout ignored (already off)');
      debugSend({ payload: '[PIR] pir_off_timeout ignored', _debug: true });
    }
  }
  function onMaxOnTimeout() {
    dbg('timers', 'onMaxOnTimeout; force off (max_on)');
    if (state.light_on) {
      clearRuntimeTimer('max_on');
      emitOff('max_on');
    } else dbg('timers', 'onMaxOnTimeout no-op (already off)');
  }

  // Restore timers persisted in state.timers when Function starts
  function restoreTimersIfNeeded() {
    if (state.__timers_restored) { dbg('timers', 'restore already done'); return; }
    // Suppress debug during restore to avoid replay floods
    suppressReplayDebug = true;
    dbg('general', 'restoreTimersIfNeeded starting; persisted timers:', state.timers);
    state.__timers_restored = true;
    nodeCtx.set('pir_state', state);
    let restored = 0;
    for (const name of Object.keys(state.timers || {})) {
      const entry = state.timers[name];
      if (!entry || !entry.until) continue;
      dbg('timers', 'restoring', name, 'until', entry.until);
      if (name === 'pir_off') { scheduleTimerAt('pir_off', entry.until, onPirOffTimeout); restored++; }
      else if (name === 'max_on') { scheduleTimerAt('max_on', entry.until, onMaxOnTimeout); restored++; }
      else { scheduleTimerAt(name, entry.until, () => { dbg('timers', 'restored generic timer fired', name); }); restored++; }
    }
    startWatcher();
    // short pause to allow initial messages to settle, then re-enable debug and show a single summary
    setTimeout(() => {
      suppressReplayDebug = false;
      debugSend({ payload: '[PIR] restore complete - timers restored: ' + restored, _debug: true });
    }, 250);
  }

  // === Node main handler: executed for each incoming message ===
  (function main() {
    restoreTimersIfNeeded();

    // Set per-message debug enable (allow msg._debug_all to override)
    msgDbgEnabled = cfg.dbg || (typeof msg !== 'undefined' && !!msg._debug_all);

    // Normalize commonly used incoming fields
    const topic = msg.topic;
    const payload = msg.payload;
    const entity = msg.entity_id || msg.entity || (msg.data && msg.data.entity_id) || '';
    const luxProp = (typeof msg.lux !== 'undefined') ? msg.lux : undefined;
    const desativaProp = (typeof msg.desativa !== 'undefined') ? msg.desativa : ((typeof msg.desativa1 !== 'undefined') ? msg.desativa1 : undefined);
    const desativa2Prop = (typeof msg.desativa2 !== 'undefined') ? msg.desativa2 : undefined;
    const desativa3Prop = (typeof msg.desativa3 !== 'undefined') ? msg.desativa3 : undefined;
    const lightStateProp = (typeof msg.light_state !== 'undefined') ? msg.light_state : undefined;

    // NEW: init handler -> apply initial payload to state (useful right after deploy)
    if (topic === 'init' || msg.initial === true) {
      const payloadObj = (payload && typeof payload === 'object') ? payload : (msg || {});
      const applied = applyInitPayload(payloadObj);
      if (!applied) {
        debugSend({ payload: '[PIR] init received but no recognized fields applied', _debug: true });
        dbg('init', 'init received but nothing applied', payloadObj);
      }
      return null;
    }

    // status query: emit snapshot (debug and output[1] for convenience)
    if (topic === 'status' || msg._status === true) {
      debugSend({ payload: '[PIR] state snapshot', _state: JSON.parse(JSON.stringify(state)), _debug: true });
      node.send([null, { payload: 'status', _state: JSON.parse(JSON.stringify(state)) }, null]);
      return null;
    }

    // runtime override for desativa_lux_manual: msg.desativa_lux_manual (boolean) takes precedence,
    // otherwise fallback to persisted state.desativa_lux_manual or env cfg.desativa_lux_manual.
    const runtimeDesativaLuxManual = (typeof msg.desativa_lux_manual !== 'undefined')
      ? Boolean(msg.desativa_lux_manual)
      : (typeof state.desativa_lux_manual !== 'undefined' ? Boolean(state.desativa_lux_manual) : cfg.desativa_lux_manual);

    dbg('config', 'desativa_lux_manual(cfg)=', cfg.desativa_lux_manual, 'runtime_override(msg)=', typeof msg.desativa_lux_manual !== 'undefined' ? msg.desativa_lux_manual : '(none)', 'effective=', runtimeDesativaLuxManual);

    dbg('general', 'incoming msg', { topic, payload, entity, luxProp, desativaProp, desativa2Prop, desativa3Prop, lightStateProp });

    // If desativa_lux_manual is enabled runtime and a pir_off is scheduled while in manual mode, clear it
    if (runtimeDesativaLuxManual && state.timers && state.timers['pir_off'] && state.modo === 'manual') {
      dbg('config', 'runtimeDesativaLuxManual=true -> clearing pir_off scheduled while in manual mode');
      clearRuntimeTimer('pir_off');
      if (state.pending_reactivate) {
        state.pending_reactivate = false;
        state.pending_reactivate_since = 0;
        nodeCtx.set('pir_state', state);
        dbg('config', 'cleared pending_reactivate due to desativa_lux_manual');
      }
    }

    // ---- RESET control (external) ----
    if (topic === 'reset' || payload === '__reset') {
      dbg('general', 'received reset');
      Object.keys(runtimeTimers).forEach(clearRuntimeTimer);
      state = { modo: 'livre', light_on: false, lastLux: null, lastPirAt: 0, pir_active: false, pending_pir: false, pending_reactivate: false, pending_reactivate_since: 0, desativa1: false, desativa2: false, desativa3: false, desativa_lux_manual: cfg.desativa_lux_manual, timers: {}, ignore_until: 0, _last_self_off_ms: 0, _last_self_off_entity: '' };
      nodeCtx.set('pir_state', state);
      node.status({ fill: 'grey', shape: 'dot', text: 'reset' });
      debugSend({ payload: '[PIR] reset done', _debug: true });
      return null;
    }

    // ---- DESATIVA_LUX_MANUAL updates ----
    if (typeof msg.desativa_lux_manual !== 'undefined') {
      const val = parseBoolAny(msg.desativa_lux_manual);
      if (typeof val !== 'undefined') {
        state.desativa_lux_manual = Boolean(val);
        nodeCtx.set('pir_state', state);
        dbg('state', 'desativa_lux_manual set to', state.desativa_lux_manual);
        debugSend({ payload: '[PIR] desativa_lux_manual updated to ' + state.desativa_lux_manual, _debug: true });
      }
      return null;
    }

    // ---- LUX updates ----
    if (topic === 'lux' || normEntity(entity) === normEntity(cfg.lux_entidade) || typeof luxProp !== 'undefined') {
      const candidate = (typeof luxProp !== 'undefined') ? luxProp : payload;
      const lux = extractLuxFromPayload(candidate);
      if (!isNaN(lux)) {
        // store last reading and persist
        state.lastLux = lux;
        nodeCtx.set('pir_state', state);
        dbg('lux', 'lux update received (extracted)', lux, 'entity=', entity);

        // If lux_max enabled and light is ON in modo pir, schedule pir_off if lux >= lux_max
        if (luxMaxActive && state.light_on && state.modo === 'pir') {
          dbg('lux', 'checking lux_max while ON', { lastLux: state.lastLux, lux_max: cfg.lux_max });
          if (state.lastLux >= cfg.lux_max) {
            dbg('lux', 'lux >= lux_max -> schedule pir_off if not already scheduled');
            if (!(state.timers && state.timers['pir_off'])) {
              if (state.pir_active) {
                state.pending_reactivate = true;
                state.pending_reactivate_since = Date.now();
                nodeCtx.set('pir_state', state);
                dbg('lux', 'set pending_reactivate due to lux >= lux_max while pir_active', { pending_reactivate_since: state.pending_reactivate_since });
              }
              scheduleTimer('pir_off', cfg.t_off_s * 1000, onPirOffTimeout);
              debugSend({ payload: '[PIR] scheduled pir_off due to lux_above_max', _debug: true });
            } else dbg('lux', 'pir_off already scheduled; ignoring additional lux event');
          }
        }

        // If not disabled, check lux_max_manual in manual mode
        if (!runtimeDesativaLuxManual && luxMaxManualActive && state.light_on && state.modo === 'manual') {
          dbg('lux', 'checking lux_max_manual while ON (manual mode)', { lastLux: state.lastLux, lux_max_manual: cfg.lux_max_manual });
          if (state.lastLux >= cfg.lux_max_manual) {
            dbg('lux', 'lux >= lux_max_manual -> schedule pir_off if not already scheduled (manual mode)');
            if (!(state.timers && state.timers['pir_off'])) {
              if (state.pir_active) {
                state.pending_reactivate = true;
                state.pending_reactivate_since = Date.now();
                nodeCtx.set('pir_state', state);
                dbg('lux', 'set pending_reactivate due to lux >= lux_max_manual while pir_active', { pending_reactivate_since: state.pending_reactivate_since });
              }
              scheduleTimer('pir_off', cfg.t_off_s * 1000, onPirOffTimeout);
              debugSend({ payload: '[PIR] scheduled pir_off due to lux_above_max_manual', _debug: true });
            } else dbg('lux', 'pir_off already scheduled; ignoring additional lux event (manual)');
          }
        } else if (runtimeDesativaLuxManual && luxMaxManualActive && state.light_on && state.modo === 'manual') {
          dbg('lux', 'desativa_lux_manual is true -> skipping lux_max_manual check (manual mode)');
        }

        // pending_pir -> activation when lux drops below lux_min
        if (luxMinActive && state.pending_pir && state.pir_active && !state.light_on && state.modo !== 'manual') {
          const age = Date.now() - (state.lastPirAt || 0);
          dbg('lux', 'pending_pir check', { age_ms: age, pendingPirAgeLimit: cfg.pending_pir_max_ms, lastLux: state.lastLux, lux_min: cfg.lux_min });
          if (age <= cfg.pending_pir_max_ms) {
            if (typeof state.lastLux === 'number' && state.lastLux < cfg.lux_min) {
              dbg('lux', 'lux dropped below lux_min -> triggering ON as if PIR pulse (pending_pir)', { lastLux: state.lastLux, lux_min: cfg.lux_min });
              clearRuntimeTimer('pir_off');
              state.light_on = true;
              state.modo = 'pir';
              state.pending_pir = false;
              nodeCtx.set('pir_state', state);
              scheduleTimer('max_on', cfg.t_max_on_m * 60 * 1000, onMaxOnTimeout);
              node.status({ fill: 'blue', shape: 'dot', text: 'luz: on (pir, from pending)' });
              node.send([{ payload: 'on', _reason: 'pir_pending_lux_drop', _state: JSON.parse(JSON.stringify(state)), entity_id: cfg.input_entidade }, null, null]);
              debugSend({ payload: '[PIR] emitted ON (pending->lux drop)', _debug: true });
            }
          } else {
            dbg('lux', 'pending_pir expired (too old) -> clearing pending', { age_ms: age, pendingPirAgeLimit: cfg.pending_pir_max_ms });
            state.pending_pir = false;
            nodeCtx.set('pir_state', state);
          }
        }

        // pending_reactivate -> reactivation when lux drops below lux_min
        if (state.pending_reactivate && state.pir_active && !state.light_on) {
          const ageR = Date.now() - (state.pending_reactivate_since || 0);
          dbg('lux', 'pending_reactivate check', { age_ms: ageR, pendingReactivateAgeLimit: cfg.pending_reactivate_max_ms, lastLux: state.lastLux, lux_min: cfg.lux_min });
          if (ageR <= cfg.pending_reactivate_max_ms) {
            if (typeof state.lastLux === 'number' && state.lastLux < cfg.lux_min) {
              dbg('lux', 'lux dropped below lux_min -> re-triggering ON due to pending_reactivate', { lastLux: state.lastLux, lux_min: cfg.lux_min });
              clearRuntimeTimer('pir_off');
              state.light_on = true;
              state.modo = 'pir';
              state.pending_reactivate = false;
              state.pending_reactivate_since = 0;
              nodeCtx.set('pir_state', state);
              scheduleTimer('max_on', cfg.t_max_on_m * 60 * 1000, onMaxOnTimeout);
              node.status({ fill: 'blue', shape: 'dot', text: 'luz: on (pir, from pending_reactivate)' });
              node.send([{ payload: 'on', _reason: 'pir_reactivate_lux_drop', _state: JSON.parse(JSON.stringify(state)), entity_id: cfg.input_entidade }, null, null]);
              debugSend({ payload: '[PIR] emitted ON (pending_reactivate->lux drop)', _debug: true });
            } else {
              dbg('lux', 'pending_reactivate remains; lux not below threshold yet', { lastLux: state.lastLux, lux_min: cfg.lux_min });
            }
          } else {
            dbg('lux', 'pending_reactivate expired -> clearing', { age_ms: ageR, pendingReactivateAgeLimit: cfg.pending_reactivate_max_ms });
            state.pending_reactivate = false;
            state.pending_reactivate_since = 0;
            nodeCtx.set('pir_state', state);
          }
        }

        debugSend({ payload: '[PIR][lux] lastLux updated ' + state.lastLux, _debug: true });
        return null;
      }
      dbg('lux', 'invalid lux payload (could not extract number)', payload);
      return null;
    }

    // ---- DESATIVA (disable) updates handling ----
    if (typeof msg.desativa !== 'undefined' || typeof msg.desativa1 !== 'undefined' || typeof msg.desativa2 !== 'undefined' || typeof msg.desativa3 !== 'undefined' || topic === 'desativa' || topic === 'desativa1' || topic === 'desativa2' || topic === 'desativa3' || normEntity(entity) === normEntity(cfg.desativa_entidade) || normEntity(entity) === normEntity(cfg.desativa_entidade2) || normEntity(entity) === normEntity(cfg.desativa_entidade3)) {
      dbg('state', 'desativa message', { topic, payload, entity });
      let matched = false;

      const val1 = (typeof desativaProp !== 'undefined') ? parseBoolAny(desativaProp) : ((entity && cfg.desativa_entidade && normEntity(entity) === normEntity(cfg.desativa_entidade)) ? parseBoolAny(payload) : undefined);
      const val2 = (typeof desativa2Prop !== 'undefined') ? parseBoolAny(desativa2Prop) : ((entity && cfg.desativa_entidade2 && normEntity(entity) === normEntity(cfg.desativa_entidade2)) ? parseBoolAny(payload) : undefined);
      const val3 = (typeof desativa3Prop !== 'undefined') ? parseBoolAny(desativa3Prop) : ((entity && cfg.desativa_entidade3 && normEntity(entity) === normEntity(cfg.desativa_entidade3)) ? parseBoolAny(payload) : undefined);

      if (topic === 'desativa1') { state.desativa1 = Boolean(parseBoolAny(payload)); matched = true; dbg('state', 'desativa1 (topic) set to', state.desativa1); }
      if (topic === 'desativa2') { state.desativa2 = Boolean(parseBoolAny(payload)); matched = true; dbg('state', 'desativa2 (topic) set to', state.desativa2); }
      if (topic === 'desativa3') { state.desativa3 = Boolean(parseBoolAny(payload)); matched = true; dbg('state', 'desativa3 (topic) set to', state.desativa3); }

      if (typeof val1 !== 'undefined') { state.desativa1 = Boolean(val1); matched = true; dbg('state', 'desativa1 set to', state.desativa1); }
      if (typeof val2 !== 'undefined') { state.desativa2 = Boolean(val2); matched = true; dbg('state', 'desativa2 set to', state.desativa2); }
      if (typeof val3 !== 'undefined') { state.desativa3 = Boolean(val3); matched = true; dbg('state', 'desativa3 set to', state.desativa3); }

      if (!matched && topic === 'desativa') {
        const fallback = parseBoolAny(payload);
        state.desativa1 = state.desativa2 = state.desativa3 = Boolean(fallback);
        matched = true;
        dbg('state', 'desativa all set to', fallback);
      }

      nodeCtx.set('pir_state', state);

      // If any desativa switched to true while lamp is ON and in modo 'pir', schedule pir_off(t_off_s)
      if ((state.desativa1 || state.desativa2 || state.desativa3) && state.light_on && state.modo === 'pir') {
        dbg('state', 'desativa activated while light_on in modo pir; scheduling pir_off', { desativa1: state.desativa1, desativa2: state.desativa2, desativa3: state.desativa3 });
        clearRuntimeTimer('max_on');
        if (!(state.timers && state.timers['pir_off'])) {
          scheduleTimer('pir_off', cfg.t_off_s * 1000, onPirOffTimeout);
          debugSend({ payload: '[PIR] scheduled pir_off due to desativa activation', _debug: true });
        } else dbg('timers', 'pir_off already scheduled (desativa activation)');
      } else {
        if (state.pending_pir && (state.desativa1 || state.desativa2 || state.desativa3)) {
          dbg('state', 'clearing pending_pir due to desativa activation');
          state.pending_pir = false;
          nodeCtx.set('pir_state', state);
        }
        if (state.pending_reactivate && (state.desativa1 || state.desativa2 || state.desativa3)) {
          dbg('state', 'clearing pending_reactivate due to desativa activation');
          state.pending_reactivate = false;
          state.pending_reactivate_since = 0;
          nodeCtx.set('pir_state', state);
        }
        debugSend({ payload: '[PIR] desativa flags updated', _debug: true, desativa1: state.desativa1, desativa2: state.desativa2, desativa3: state.desativa3 });
      }
      return null;
    }

    // ---- MANUAL mode ----
    if (msg.manual === true) {
      state.light_on = true;
      state.modo = 'manual';
      clearRuntimeTimer('pir_off');
      clearRuntimeTimer('max_on');
      state.ignore_until = 0;
      nodeCtx.set('pir_state', state);
      node.status({ fill: 'yellow', shape: 'dot', text: 'luz: on (manual)' });
      dbg('general', 'entered manual mode');
      debugSend({ payload: '[PIR] entered manual mode', _debug: true });
      return null;
    }
    if (msg.manual === false) {
      if (state.modo === 'manual') {
        state.modo = 'livre';
        state.light_on = false;
        clearRuntimeTimer('pir_off');
        clearRuntimeTimer('max_on');
        nodeCtx.set('pir_state', state);
        node.status({ fill: 'grey', shape: 'ring', text: 'manual off -> livre' });
        dbg('general', 'exited manual mode (manual=false)');
        node.send([null, { payload: 'off', _reason: 'manual_off', entity_id: cfg.input_entidade }, null]);
      }
      return null;
    }

    // ---- PIR presence handling (payload 'on'/'off' or topic 'pir') ----
    if (topic === 'pir' || (typeof payload === 'string' && (payload === 'on' || payload === 'off'))) {
      const s = String(payload);

      // PIR ON event
      if (s === 'on') {
        dbg('pir', 'pir event received (ON)');
        const now = Date.now();
        if (state.ignore_until && now < state.ignore_until) {
          dbg('pir', 'ignored PIR ON due to ignore_until', { now, ignore_until: state.ignore_until });
          debugSend({ payload: '[PIR] PIR ON ignored due to ignore window', _debug: true });
          return null;
        }

        // update last PIR timestamp and mark pir_active
        state.lastPirAt = Date.now();
        state.pir_active = true;
        nodeCtx.set('pir_state', state);
        dbg('pir', 'updated lastPirAt and set pir_active', state.lastPirAt);

        // If a pir_off timer exists, decide whether to cancel it (based on lux conditions)
        if (state.timers && state.timers['pir_off']) {
          let canCancel = true;
          if (!hasLuxEntity) canCancel = true;
          else if (typeof state.lastLux !== 'number') canCancel = true;
          else {
            if (luxMaxActive && !(state.lastLux < cfg.lux_max)) canCancel = false;
            if (luxMinActive && !(state.lastLux >= cfg.lux_min)) canCancel = false;
          }
          if (canCancel && state.modo !== 'manual') {
            dbg('timers', 'canceling existing pir_off due to PIR ON (lux ok or missing)');
            clearRuntimeTimer('pir_off');
          } else dbg('timers', 'keeping existing pir_off due to lux conditions or manual mode');
        }

        // Block activation if any desativa flag is true
        if (state.desativa1 || state.desativa2 || state.desativa3) {
          dbg('pir', 'activation blocked by desativa flag', { desativa1: state.desativa1, desativa2: state.desativa2, desativa3: state.desativa3 });
          state.pending_pir = false;
          nodeCtx.set('pir_state', state);
          debugSend({ payload: '[PIR] activation blocked by desativa', _debug: true });
          return null;
        }
        // If manual mode, ignore PIR for on/off control
        if (state.modo === 'manual') {
          dbg('pir', 'in manual mode -> ignoring PIR for on/off control');
          debugSend({ payload: '[PIR] pir ignored in manual mode', _debug: true });
          return null;
        }

        // Check lux_min at activation time (if active)
        if (luxMinActive && typeof state.lastLux === 'number') {
          dbg('lux', 'checking lux_min at activation', { lastLux: state.lastLux, lux_min: cfg.lux_min });
          if (state.lastLux >= cfg.lux_min) {
            dbg('lux', 'lux >= lux_min -> not turning on');
            state.pending_pir = true;
            nodeCtx.set('pir_state', state);
            debugSend({ payload: '[PIR] not turning on: lux >= lux_min (pending set)', _debug: true });
            return null;
          }
        }

        // Also check lux_max at activation if we have a reading
        if (luxMaxActive && typeof state.lastLux === 'number') {
          dbg('lux', 'checking lux_max at activation', { lastLux: state.lastLux, lux_max: cfg.lux_max });
          if (state.lastLux >= cfg.lux_max) {
            dbg('lux', 'lux >= lux_max at activation -> not turning on');
            state.pending_pir = false;
            nodeCtx.set('pir_state', state);
            debugSend({ payload: '[PIR] not turning on: lux >= lux_max', _debug: true });
            return null;
          }
        }

        // Perform ON action if light currently off
        if (!state.light_on) {
          state.light_on = true;
          state.modo = 'pir';
          state.pending_pir = false;
          nodeCtx.set('pir_state', state);
          scheduleTimer('max_on', cfg.t_max_on_m * 60 * 1000, onMaxOnTimeout);
          node.status({ fill: 'blue', shape: 'dot', text: 'luz: on (pir)' });
          const outOn = { payload: 'on', _reason: 'pir', _state: JSON.parse(JSON.stringify(state)), entity_id: cfg.input_entidade };
          node.send([outOn, null, null]);
          debugSend({ payload: '[PIR] emitted ON (pir)', _debug: true });
          return null;
        }

        // Light already on; treat as timer refresh / no further action
        dbg('pir', 'light already on -> refreshed timers only');
        debugSend({ payload: '[PIR] refreshed timers only', _debug: true });
        return null;
      }

      // PIR OFF event
      if (s === 'off') {
        dbg('pir', 'pir event received (OFF)');
        state.lastPirAt = Date.now();
        state.pir_active = false;
        state.pending_pir = false;
        state.pending_reactivate = false;
        state.pending_reactivate_since = 0;
        nodeCtx.set('pir_state', state);

        if (state.modo === 'manual') {
          dbg('pir', 'in manual mode -> ignoring PIR OFF for automatic control');
          debugSend({ payload: '[PIR] pir OFF ignored in manual mode', _debug: true });
          return null;
        }

        if (!(state.timers && state.timers['pir_off'])) {
          dbg('pir', 'scheduling pir_off due to explicit OFF input, t_off_s=', cfg.t_off_s);
          scheduleTimer('pir_off', cfg.t_off_s * 1000, onPirOffTimeout);
          debugSend({ payload: '[PIR] scheduled pir_off due to explicit PIR OFF', _debug: true });
        } else {
          dbg('pir', 'pir_off already scheduled; ignoring additional OFF');
          debugSend({ payload: '[PIR] pir_off already scheduled; ignoring additional OFF', _debug: true });
        }
        return null;
      }
    }

    // Unknown/unhandled message
    dbg('general', 'unknown message, no-op');
    return null;
  })(); // end main

})(); // end function
